import styles from './page.module.css';
import {TitleRequest, TitleResponse} from "@/proto/generated/Title_pb";
import {grpcRequest} from "@/utils/grpcHandler";

export default async function HomePage(
    {params}: { params: Promise<{ id: string }> }
) {

  const title = await fetchTitle()

  return (
      <div className={styles.container}>
        <h1 className={styles.title}>Welcome to Devume!</h1>
        <p className={styles.description}>
          The best place for developers to showcase their portfolios.
        </p>
      </div>
  );
}

async function fetchTitle() {
  try {
    const request = new TitleRequest()

    // Use the promise wrapper
    const response: TitleResponse = await grpcRequest('getTitle', request);

    // Assuming the response has a `toObject()` method from protobuf
    console.log(`Title response : ${response.getTitle()}`)
  } catch (error) {
    console.error('Failed to fetch user:', error);
    return null;
  }
}
