import * as grpc from '@grpc/grpc-js';
import {TitleClient} from "@/proto/generated/Title_grpc_pb";

let titleClientInstance: TitleClient | null = null;

export function getTitleClient(): GrpcClient {
  if (!clientInstance) {
    const grpcApiUrl = process.env.GRPC_API_URL;
    if (!grpcApiUrl) {
      throw new Error('gRPC API URL is not defined in environment variables.');
    }

    console.log(`Initializing gRPC client for URL: ${grpcApiUrl}`);
    clientInstance = new GrpcClient(grpcApiUrl, grpc.credentials.createInsecure());
  }
  return clientInstance;
}

export function grpcRequest<TRequest, TResponse>(
    methodName: string,
    request: TRequest
): Promise<TResponse> {
  return new Promise((resolve, reject) => {
    (getGrpcClient() as any)[methodName](request, (error: grpc.ServiceError | null, response: TResponse) => {
      if (error) {
        console.error(`gRPC Error (${methodName}):`, error);
        return reject(error);
      }

      console.log(`response!!!!!!! : `, response)

      resolve(response);
    });
  });
}